args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?dir ?dirLabel (COALESCE(?d1, ?d2, ?d3) AS ?deathDate) WHERE {
  VALUES ?film { dbr:Majhli_Didi dbr:Dream_of_the_Rhine }
  ?film dbo:director ?dir .
  OPTIONAL { ?dir dbo:deathDate ?d1. }
  OPTIONAL { ?dir dbp:deathDate ?d2. }
  OPTIONAL { ?dir dbp:death_date ?d3. }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?dir rdfs:label ?dirLabel . FILTER (lang(?dirLabel) = "en") }
}
ORDER BY DESC(?deathDate)

